/**
 * Decodes an encoded uri element, exactly once and as utf-8 (a character can be encoded as
 * multiple bytes, so they must be decoded together, not one by one).
 * Sequences that are not valid (a lone '%' or bytes that are not utf-8) are kept as-is.
 */
static String decode(String encoded) {
    // nothing to decode (common case)
    if (encoded.indexOf('%') == -1) return encoded;

    var decoded = new StringBuilder();
    var bytes = new ByteArrayOutputStream(); // encoded bytes pending to be decoded
    var raw = new StringBuilder(); // their original representation, to restore them if invalid

    for (var i = 0; i < encoded.length(); ) {
        var value = encoded.charAt(i) == '%' && i + 2 < encoded.length()
                ? hexToInt(encoded.charAt(i + 1), encoded.charAt(i + 2))
                : -1;
        if (value != -1) {
            // an encoded byte, accumulate it (the character may need more of them)
            bytes.write(value);
            raw.append(encoded, i, i + 3);
            i += 3;
        } else {
            // a literal character, flush the pending bytes first
            flush(bytes, raw, decoded);
            decoded.append(encoded.charAt(i));
            i++;
        }
    }
    flush(bytes, raw, decoded);

    return decoded.toString();
}

/**
 * Appends the accumulated bytes to the builder decoded as utf-8,
 * or their raw content if they are not a valid utf-8 sequence.
 */
private static void flush(ByteArrayOutputStream bytes, StringBuilder raw, StringBuilder decoded) {
    if (bytes.size() > 0) {
        try {
            decoded.append(StandardCharsets.UTF_8.newDecoder()
                    .onMalformedInput(CodingErrorAction.REPORT)
                    .onUnmappableCharacter(CodingErrorAction.REPORT)
                    .decode(ByteBuffer.wrap(bytes.toByteArray())));
        } catch (CharacterCodingException e) {
            // not utf-8, keep them encoded
            decoded.append(raw);
        }
        bytes.reset();
        raw.setLength(0);
    }
}

/**
 * Converts two hexadecimal characters into its numeric value, -1 if any of them is not hexadecimal
 */
private static int hexToInt(char high, char low) {
    var highValue = hexToInt(high);
    var lowValue = hexToInt(low);
    return highValue == -1 || lowValue == -1 ? -1 : (highValue << 4) + lowValue;
}

/**
 * Converts an hexadecimal character into its numeric value, -1 if it is not hexadecimal
 */
private static int hexToInt(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

